import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

/** Generated by scripts/build-place-centroids.ts; read like the place URL projection. */
const CENTROIDS_PATH = 'data/place-centroids-gauteng-v0.1.json';

export type PlaceCentroidEntry = {
  canonicalPlaceId: string;
  naturalKey: string;
  level: 'city' | 'suburb';
  parentCityPlaceId: string | null;
  lat: number | null;
  lng: number | null;
  matchMethod: string;
};

export type PlaceCentroidIndex = {
  entries: readonly PlaceCentroidEntry[];
  byPlaceId: ReadonlyMap<string, PlaceCentroidEntry>;
};

let cached: PlaceCentroidIndex | undefined;

export function buildPlaceCentroidIndex(
  entries: readonly PlaceCentroidEntry[],
): PlaceCentroidIndex {
  return { entries, byPlaceId: new Map(entries.map(entry => [entry.canonicalPlaceId, entry])) };
}

/**
 * Loads the committed centroid file. A missing file yields an empty index (no
 * place has a centre), which the guide renders as an honest empty state.
 */
export function loadPlaceCentroids(): PlaceCentroidIndex {
  if (cached) return cached;
  let raw: string;
  try {
    raw = readFileSync(resolve(process.cwd(), CENTROIDS_PATH), 'utf8');
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      cached = buildPlaceCentroidIndex([]);
      return cached;
    }
    throw error;
  }
  const parsed = JSON.parse(raw) as { entries?: PlaceCentroidEntry[] };
  if (!Array.isArray(parsed.entries)) {
    throw new Error('Place centroid file has an unsupported shape.');
  }
  cached = buildPlaceCentroidIndex(parsed.entries);
  return cached;
}

/** Great-circle distance in kilometres. */
export function haversineKm(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const rad = (degrees: number) => (degrees * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h =
    Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371.0088 * Math.asin(Math.sqrt(h));
}
